Load the cached dates from column A, compute each date’s weekday with Monday as 1, and write those numbers to B2:B16. Then write the corresponding full English day names to the graded cells C2:C16. Save the workbook without altering formats.

```python
import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["WEEKDAY"]
vws = vals["WEEKDAY"]

day_names = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
]

def get_python_weekday(value):
    """Return Python weekday: Monday=0 ... Sunday=6."""
    if value is None:
        return None

    if isinstance(value, datetime):
        return value.weekday()

    if isinstance(value, date):
        return value.weekday()

    if isinstance(value, (int, float)):
        try:
            from openpyxl.utils.datetime import from_excel
            return from_excel(value).weekday()
        except Exception:
            return None

    if isinstance(value, str):
        s = value.strip()
        formats = [
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
            "%d/%m/%Y %H:%M:%S",
            "%d/%m/%Y",
        ]
        for fmt in formats:
            try:
                return datetime.strptime(s, fmt).weekday()
            except ValueError:
                pass

    return None

for row in range(2, 17):
    a_val = vws.cell(row=row, column=1).value
    wd = get_python_weekday(a_val)

    if wd is None:
        ws.cell(row=row, column=2).value = None
        ws.cell(row=row, column=3).value = None
        continue

    b_val = wd + 1          # Monday=1 ... Sunday=7
    c_val = day_names[wd]   # actual day name

    ws.cell(row=row, column=2).value = b_val
    ws.cell(row=row, column=3).value = c_val

    print(row, a_val, b_val, c_val)

wb.save(OUT)
